"""Display width (SPEC §14.1), the measure a serializer lays lines out by.

**The table is ours, not the host's** (`_wcwidth.py`, generated by
`tools/gen_wcwidth_table.py` and pinned to Unicode 14.0.0 like the
identifier table). `unicodedata.east_asian_width` answers for whatever
Unicode the interpreter carries, so the same document would break its lines
differently on 3.11 and 3.13 — layout is output, and §14 fixes output
exactly.
"""

from __future__ import annotations

from bisect import bisect_right

from ._wcwidth import WIDE, ZERO

_ZERO_LOWS = tuple(lo for lo, _ in ZERO)
_WIDE_LOWS = tuple(lo for lo, _ in WIDE)
_EMOJI_PRESENTATION = "\ufe0f"


def _in(lows: tuple, table: tuple, cp: int) -> bool:
    i = bisect_right(lows, cp) - 1
    return i >= 0 and cp <= table[i][1]


def char_width(ch: str) -> int:
    """0, 1, or 2 for one code point, by the pinned table."""
    cp = ord(ch)
    if _in(_ZERO_LOWS, ZERO, cp):
        return 0
    return 2 if _in(_WIDE_LOWS, WIDE, cp) else 1


def text_width(text: str) -> int:
    """The width of a line: the sum of its code points' widths, except that
    U+FE0F makes the character before it count 2 (`❤\ufe0f` is 2). The model may
    overcount a rendering, never undercount one."""
    total, last = 0, 0
    for ch in text:
        if ch == _EMOJI_PRESENTATION and last:
            total += 2 - last
            last = 2
            continue
        last = char_width(ch)
        total += last
    return total
